<script setup lang="ts">
import { useDialogDraft } from '../dialog-draft'
import { useAdminListRoute } from '../navigation'
import { onDeactivated, computed, ref, watch } from 'vue'
import type { UserInfo } from '../api'
import { useAdminPage } from '../admin-page'
import { getOrders, getOrder, getPlans, syncOrder, cancelOrder, reviewRefund, syncRefund, exportOrders, orderStatuses, refundStatuses, choices, yuan, dateTime, type Order, type OrderFilter } from '../growth'
const props = defineProps<{ user: UserInfo }>()
const items = ref<Order[]>([]), summary = ref({ orders: 0, paid_fen: 0, refunded_fen: 0 }), total = ref(0), pageNumber = ref(1), status = ref('all'), q = ref(''), start = ref(''), end = ref(''), online = ref(false)
const selected = ref<Order | null>(null), dialog = ref(false), action = ref<'approve' | 'reject'>('reject'), reply = ref(''), confirmRefund = ref(false), cancelConfirm = ref(false)
const channelLabel = (item: Order) => item.payment_channel === 'virtual' ? '小程序内支付' : '微信支付'
const platformNames: Record<string, string> = { ios: 'iPhone（苹果 IAP）', android: '安卓', ohos: '鸿蒙', windows: 'Windows', mac: 'macOS', devtools: '开发者工具' }
const platformLabel = (item: Order) => platformNames[item.device_platform] || item.device_platform || '未记录'
const accountLabel = (item: Order) => item.nickname || item.username
/** 昵称可重复且微信用户常被随机分配同名昵称，补一行唯一登录账号便于区分 */
const accountNote = (item: Order) => item.nickname && item.nickname !== item.username ? '账号：' + item.username : ''
const iosVirtualRefund = computed(() => !!selected.value && selected.value.payment_channel === 'virtual' && (selected.value.device_platform === 'ios' || [7, 8].includes(selected.value.virtual_order_type)))
const filter = (): OrderFilter => ({ status: status.value === 'all' ? '' : status.value, q: q.value.trim(), start_date: start.value, end_date: end.value })
let plansPromise: ReturnType<typeof getPlans> | undefined
onDeactivated(() => { plansPromise = undefined })
function checkoutPlans() { return plansPromise ||= getPlans().catch(cause => { plansPromise = undefined; throw cause }) }
const page = useAdminPage(async valid => { const [result, plans] = await Promise.all([getOrders(filter(), (pageNumber.value - 1) * 20), checkoutPlans()]); if (valid()) { items.value = result.items; total.value = result.total; summary.value = result.summary; online.value = plans.checkout_enabled } }, () => { dialog.value = false; cancelConfirm.value = false })
const { error, notice, loading, busy } = page
const routeState = useAdminListRoute('orders', { q, status, start, end, page: pageNumber }, () => { void page.load() })
watch(pageNumber, page.load); watch(status, () => { if (routeState.restoring) return; if (pageNumber.value === 1) void page.load(); else pageNumber.value = 1 })
function search() { if (routeState.restoring) return; if (pageNumber.value === 1) void page.load(); else pageNumber.value = 1 }
function open(item: Order) {
  selected.value = item; action.value = 'reject'; reply.value = ''; confirmRefund.value = false; cancelConfirm.value = false; dialog.value = true
  void page.act(async valid => { const result = await getOrder(item.id); if (valid() && dialog.value && selected.value?.id === item.id) selected.value = result })
}
function sync() { if (!selected.value) return; void page.act(async valid => { const item = selected.value!; const result = item.refund && ['processing', 'abnormal'].includes(item.refund.status) ? await syncRefund(props.user.id, item.refund.id) : await syncOrder(props.user.id, item.id); if (valid()) { selected.value = result; notice.value = '已查询微信最新状态'; await page.load() } }) }
function cancel() { if (!selected.value || !cancelConfirm.value) return; void page.act(async valid => { const result = await cancelOrder(props.user.id, selected.value!.id); if (valid()) { selected.value = result; cancelConfirm.value = false; notice.value = '已核对并关闭未付款订单'; await page.load() } }) }
function review() {
  if (!selected.value?.refund) return
  void page.act(async valid => {
    const item = selected.value!
    try { const result = await reviewRefund(props.user.id, item.refund!, action.value, reply.value.trim(), confirmRefund.value); if (valid()) { selected.value = result; draft.markSaved(); notice.value = action.value === 'approve' ? '退款已批准，最终状态以微信确认结果为准' : '退款审核结果已保存'; await page.load() } }
    catch (cause) { if (valid()) { try { const latest = await getOrder(item.id); if (valid()) selected.value = latest } catch { /* Preserve the original failure; refresh remains available. */ } } throw cause }
  })
}
function download() { void page.act(async () => { await exportOrders(props.user.id, filter()) }) }
const draft = useDialogDraft(dialog, () => [action.value, reply.value, confirmRefund.value, cancelConfirm.value], busy, '订单审核')
</script>
<template><section class="admin-section"><div class="metric-grid"><div class="metric"><div class="metric-label">筛选范围内订单</div><div class="metric-number">{{ summary.orders }}</div></div><div class="metric"><div class="metric-label">已收款（含后续退款）</div><div class="metric-number money">{{ yuan(summary.paid_fen) }}</div></div><div class="metric"><div class="metric-label">已退款</div><div class="metric-number money">{{ yuan(summary.refunded_fen) }}</div></div><div class="metric"><div class="metric-label">收款减退款</div><div class="metric-number money">{{ yuan(summary.paid_fen - summary.refunded_fen) }}</div></div></div>
  <UAlert v-if="error" :title="error" color="error" class="notice" /><UAlert v-if="notice" :title="notice" color="success" class="notice" /><UAlert v-if="!loading && !online" title="在线支付暂未启用，仍可查看和导出已有订单" color="info" class="notice" />
  <form class="order-filters" @submit.prevent="search"><UInput v-model="q" placeholder="订单号或用户账号、昵称" aria-label="搜索会员订单" maxlength="120" :disabled="loading" /><USelect v-model="status" :items="[{ value: 'all', label: '全部状态' }, ...choices(orderStatuses)]" aria-label="订单状态" :disabled="loading" /><UFormField label="创建日期起"><UInput v-model="start" type="date" aria-label="创建日期起" :disabled="loading" /></UFormField><UFormField label="创建日期止"><UInput v-model="end" type="date" aria-label="创建日期止" :disabled="loading" /></UFormField><UButton type="submit" label="查询订单" :loading="loading" /><UButton label="导出 CSV" variant="outline" :disabled="busy || loading || !total" :loading="busy" @click="download" /></form>
  <div class="data-scroll"><table class="data-table"><thead><tr><th>订单 / 套餐</th><th>用户</th><th>金额</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td class="name-cell"><strong>{{ item.plan_name }} · {{ item.plan_days }} 天</strong><div class="order-id">{{ item.id }}</div></td><td>{{ accountLabel(item) }}<div v-if="accountNote(item)" class="text-xs text-muted mt-1">{{ accountNote(item) }}</div></td><td>{{ yuan(item.amount_fen) }}</td><td>{{ orderStatuses[item.status] }}<div class="text-xs text-muted mt-1">{{ channelLabel(item) }}</div><div v-if="item.refund" class="text-xs text-muted mt-1">退款：{{ refundStatuses[item.refund.status] }}</div></td><td>{{ dateTime(item.created_at) }}</td><td><UButton :label="item.refund?.status === 'requested' ? '审核退款' : '查看订单'" variant="soft" @click="open(item)" /></td></tr><tr v-if="!items.length"><td colspan="6">{{ loading ? '正在加载订单' : '暂无匹配订单' }}</td></tr></tbody></table></div><div class="table-footer"><span>共 {{ total }} 笔 · 单次最多导出 5000 笔，超出时请缩小日期范围</span><UPagination v-if="total > 20" v-model:page="pageNumber" :total="total" :items-per-page="20" :disabled="loading" /></div>
  <UModal v-model:open="draft.model.value" title="会员订单" :dismissible="!busy" :close="!busy" :ui="{ content: 'max-w-2xl' }"><template #body><div v-if="selected" class="field-stack"><UAlert v-if="error" :title="error" color="error" /><UAlert v-if="notice" :title="notice" color="success" /><dl class="info-list order-info"><dt>订单号</dt><dd>{{ selected.id }}</dd><dt>用户</dt><dd>{{ accountLabel(selected) }}<div v-if="accountNote(selected)" class="text-xs text-muted">{{ accountNote(selected) }}</div></dd><dt>套餐快照</dt><dd>{{ selected.plan_name }} · {{ selected.plan_days }} 天</dd><dt>金额 / 状态</dt><dd>{{ yuan(selected.amount_fen) }} · {{ orderStatuses[selected.status] }}</dd><dt>支付渠道</dt><dd>{{ channelLabel(selected) }}</dd><dt>微信交易号</dt><dd>{{ selected.virtual_order_id || selected.transaction_id || '—' }}</dd><template v-if="selected.payment_channel === 'virtual'"><dt>下单设备</dt><dd>{{ platformLabel(selected) }}</dd><dt>虚拟商品</dt><dd>{{ selected.virtual_product_id || '—' }} · {{ selected.virtual_env === 1 ? '沙箱' : '正式' }}</dd><dt>发货通知</dt><dd>{{ selected.delivered_at ? dateTime(selected.delivered_at) : '待通知' }}</dd></template><dt>创建 / 付款</dt><dd>{{ dateTime(selected.created_at) }} / {{ dateTime(selected.paid_at) }}</dd></dl>
    <div class="actions-row"><UButton label="刷新订单记录" variant="outline" :disabled="busy" @click="open(selected)" /><UButton v-if="online && selected.status !== 'closed'" label="查询微信状态" :disabled="busy" :loading="busy" @click="sync" /></div>
    <div v-if="['created', 'pending'].includes(selected.status)" class="field-stack"><UCheckbox v-model="cancelConfirm" :disabled="busy" label="确认关闭这笔未付款订单" /><UButton label="关闭未付款订单" variant="outline" :disabled="!cancelConfirm || busy || (selected.status === 'pending' && selected.payment_channel !== 'virtual' && !online)" @click="cancel" /></div>
    <div v-if="selected.refund" class="refund-detail field-stack"><h3 class="font-semibold">退款申请 · {{ refundStatuses[selected.refund.status] }}</h3><p class="whitespace-pre-wrap text-sm">{{ selected.refund.reason }}</p><p v-if="selected.refund.reply" class="whitespace-pre-wrap text-sm text-muted">审核回复：{{ selected.refund.reply }}</p><p class="text-xs text-muted">更新：{{ dateTime(selected.refund.updated_at) }}</p><form v-if="selected.refund.status === 'requested'" id="refund-review" class="field-stack" @submit.prevent="review"><UAlert v-if="iosVirtualRefund" color="warning" title="iOS 虚拟支付订单需由用户在系统内申请退款" description="管理员不能代用户发起，请让用户在系统内操作，并在微信支付订单详情核对进度。" /><UFormField label="审核决定"><USelect v-model="action" :items="iosVirtualRefund ? [{ value: 'reject', label: '不通过，说明原因' }] : [{ value: 'reject', label: '不通过，说明原因' }, { value: 'approve', label: '通过并发起全额退款' }]" :disabled="busy" class="w-full" /></UFormField><UFormField label="回复用户" required><UTextarea v-model="reply" :disabled="busy" minlength="2" maxlength="500" required class="w-full" /></UFormField><template v-if="action === 'approve'"><UAlert color="warning" :title="'将向原支付账户退还 ' + yuan(selected.amount_fen)" description="微信确认退款成功后，撤回此订单未使用的会员时长。其他订单和人工续期会保留。" /><UCheckbox v-model="confirmRefund" :disabled="busy" :label="'已核对订单与退款原因，确认退还 ' + yuan(selected.amount_fen)" /></template><UButton :label="action === 'approve' ? '确认发起全额退款' : '保存审核结果'" type="submit" :color="action === 'approve' ? 'warning' : 'primary'" :loading="busy" :disabled="busy || reply.trim().length < 2 || (action === 'approve' && (!confirmRefund || !online || iosVirtualRefund))" /></form><p v-if="['abnormal', 'closed'].includes(selected.refund.status)" class="text-sm text-muted">请在{{ selected.payment_channel === 'virtual' ? '微信支付订单详情' : '微信商户平台' }}核对异常原因；处理后查询最新退款状态{{ selected.payment_channel === 'wechat' ? '并核对当日账单' : '' }}。</p></div>
  </div></template><template #footer><UButton label="关闭" :disabled="busy" @click="draft.setOpen(false)" /></template></UModal>
</section></template>
<style scoped>.order-filters { display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;margin-bottom:20px; }.money { font-size:24px;overflow-wrap:anywhere; }.order-id { margin-top:6px;font-size:11px;color:var(--ui-text-muted); }.order-info { margin-top:0;grid-template-columns:110px minmax(0,1fr); }.refund-detail { border-top:1px solid var(--ui-border);padding-top:18px; }</style>
